steps = [
    step("apispec:用 APISpec(插件 FlaskPlugin 与 MarshmallowPlugin)从 marshmallow 模型和视图函数的 YAML docstring 生成 OpenAPI 3.0.3 文档。to_dict() 的顶层键是 paths、info、openapi、components;Flask 路由 /users/<int:uid> 被转成 /users/{uid};docstring 里写的 schema: UserSchema 被解析成 {$ref: '#/components/schemas/User'};openapi-spec-validator 校验通过(文档合法)。", t=tl(S(1)), done=lidx(S(1), '顶层键', 'paths', 'components.schemas', '被解析成', '路由被转成', '文档合法'), kv=KV([['路径转换', '<int:uid> → {uid}'], ['schema 引用', '$ref 到 components'], ['校验', 'openapi-spec-validator 通过']], ['校验'])),
    step("校验规则会写进文档:name 是 {type: string, minLength: 1, maxLength: 20}(来自 Length(1, 20)),age 是 {type: integer, minimum: 0, maximum: 150}(来自 Range(0, 150)),id 是 readOnly: true(来自 dump_only),required: ['name'](来自 required=True)。文档与校验规则出自同一份 marshmallow 定义,不会各写各的。", t=tl(S(2)), done=lidx(S(2), 'name:', 'required'), kv=KV([['Length / Range', 'minLength、maxLength / minimum、maximum'], ['dump_only', 'readOnly'], ['required', 'required 列表']], ['Length / Range'])),
    step("flask-smorest:用 @blp.arguments 与 @blp.response 装饰视图,同时完成校验、序列化和生成文档,并自带 GET /openapi.json(200,openapi 3.0.3,paths 是 /users/)和 Swagger UI(GET /docs 返回 200 的 HTML)。POST 的响应码里除了 201 还自动有 422 与 default;文档合法。Swagger UI 的页面引用 CDN 上的脚本(cdn.jsdelivr.net),离线环境或有内容安全策略的站点要自己托管,我没有在浏览器里渲染它。", t=tl(S(3)), done=lidx(S(3), '/openapi.json', '/users/ 下', '文档合法', '/docs'), kv=KV([['/openapi.json', '自动生成'], ['/docs', 'Swagger UI(脚本来自 CDN)'], ['POST 响应', '201 + 自动的 422']], ['/openapi.json'])),
    step("smorest 的自动校验:POST {name: \"\", age: 200} → 422,固定格式 {code: 422, errors: {json: {age: [\"Must be greater than or equal to 0 and less than or equal to 150.\"], name: [\"Length must be between 1 and 20.\"]}}, status: \"Unprocessable Entity\"};多余的字段 extra → 422「Unknown field.」(marshmallow 默认拒绝未知字段);合法请求 → 201,id 是只读字段由服务端给出;文档里确实写了 422 响应。", t=tl(S(4)), mark=lidx(S(4), '422', '多余字段'), done=lidx(S(4), '合法', '文档里写了'), kv=KV([['校验失败', '422 + 按字段的 errors'], ['未知字段', 'Unknown field.']], ['校验失败'])),
    step("代码改了,文档跟着变:给 age 加 required=True,重新生成的 required 变成 ['age', 'name'](之前只有 ['name'])。但手写在 docstring 里的 YAML(路径、摘要、参数)不会自动更新,这部分仍然要靠人维护——所以尽量让文档来自 schema 与装饰器,少写手工 YAML。", t=tl(S(5)), done=lidx(S(5), 'required 变成'), mark=lidx(S(5), '手写的 YAML'), kv=KV([['来自 schema 的部分', '自动跟着变'], ['手写 docstring', '要人维护']], ['来自 schema 的部分'])),
]
